function prefixSum(nums: number[]): number[] {
  if (!nums || nums.length === 0) {
    return [];
  }
  const prefix: number[] = new Array(nums.length).fill(0);
  prefix[0] = nums[0];
  for (let i = 1; i < nums.length; i++) {
    prefix[i] = prefix[i - 1] + nums[i];
  }
  return prefix;
}

