public static class Solution {
  public void rotate(int[] nums, Integer k) {
      if (nums == null || nums.length == 0) return;
      if (k == null) k = 0;
      int n = nums.length;
      k = k % n;
      reverse(nums, 0, n - 1);
      reverse(nums, 0, k - 1);
      reverse(nums, k, n - 1);
  }
  private void reverse(int[] nums, int l, int r) {
      while (l < r) {
          int temp = nums[l];
          nums[l] = nums[r];
          nums[r] = temp;
          l++;
          r--;
      }
  }
}

